package com.example.domain.model.i18n

internal object DuaPl1 {
    val MAP: Map<String, DuaText> = mapOf(
        "dua_waking_up" to DuaText("Po przebudzeniu", "Chwała Allahowi, który przywrócił nam życie po tym, jak dał nam umrzeć (uśpił nas); do Niego jest powrót.", "Odmawiane zaraz po przebudzeniu jako podziękowanie Allahowi.", "Prorok ﷺ odmawiał to po przebudzeniu — rozpoczynanie dnia od wdzięczności i pamięci o życiu pozagrobowym."),
        "dua_leaving_home" to DuaText("Wychodząc z domu", "W imię Allaha, polegam na Allahu, nie ma siły ani mocy jak tylko u Allaha.", "Odmawiane przy wychodzeniu z domu w celu uzyskania ochrony.", "Temu, kto to odmówi, mówi się: zostałeś poprowadzony, zaopatrzony i chroniony — a szatan się od niego oddala."),
        "dua_anxiety_distress" to DuaText("Modlitwa w chwilach niepokoju i smutku", "O Allahu, szukam schronienia u Ciebie przed niepokojem i smutkiem, przed słabością i lenistwem, przed skąpstwem i tchórzostwem, przed ciężarem długu i uciskiem ludzi.", "W chwilach niepokoju, smutku, długów i wewnętrznego cierpienia.", "Prorok ﷺ często odmawiał tę modlitwę, szukając schronienia przed smutkiem, lenistwem i długiem."),
        "dua_sayyidul_istighfar" to DuaText("Najznamienitsza prośba o przebaczenie (Sayyidul Istighfar)", "O Allahu, Ty jesteś moim Panem, nie ma boga prócz Ciebie. Stworzyłeś mnie, a ja jestem Twoim sługą. Trzymam się Twego przymierza i obietnicy najlepiej jak potrafię. Szukam u Ciebie schronienia przed złem, które uczyniłem. Uznaję Twoją łaskę wobec mnie i uznaję mój grzech; przebacz mi, bo nikt nie przebacza grzechów oprócz Ciebie.", "Odmawiane rano i wieczorem — najlepsza modlitwa pokuty, której nauczał Prorok ﷺ.", "Kto odmówi ją wieczorem z pełnym przekonaniem i umrze tej nocy, wejdzie do Raju; podobnie ten, kto odmówi ją rano."),
        "dua_parents" to DuaText("Modlitwa za rodziców", "Panie mój, zmiłuj się nad nimi, tak jak oni wychowywali mnie, gdy byłem mały.", "Modlitwa z Koranu w podzięce za opiekę rodziców w dzieciństwie.", "Allah nakazał tę modlitwę za rodziców bezpośrednio w Koranie."),
        "dua_entering_mosque" to DuaText("Wchodząc do meczetu", "O Allahu, otwórz przede mną bramy Twojego miłosierdzia.", "Odmawiane przy wchodzeniu do meczetu prawą nogą.", "Prorok ﷺ nauczał tej modlitwy przy wchodzeniu do meczetu."),
        "dua_morning_asbahna" to DuaText("Poranne wspominanie", "Nastał dla nas poranek i władza należy do Allaha; chwała niech będzie Allahowi; nie ma boga prócz Allaha Jedynego, nie ma On współtowarzysza; do Niego należy władza i chwała, a On jest wszechmocny nad wszystkim.", "Zalecane wspominanie odmawiane rano.", "Rozpoczynanie dnia od uznania władzy i jedyności Allaha."),
        "dua_evening_amsayna" to DuaText("Wieczorne wspominanie", "Nastał dla nas wieczór i władza należy do Allaha; chwała niech będzie Allahowi; nie ma boga prócz Allaha Jedynego, nie ma On współtowarzysza; do Niego należy władza i chwała, a On jest wszechmocny nad wszystkim.", "Zalecane wspominanie odmawiane wieczorem.", "Rozpoczynanie nocy od uznania władzy i jedyności Allaha."),
        "dua_before_sleep" to DuaText("Przed snem", "W Twoje imię, o Allahu, umieram i żyję.", "Odmawiane po położeniu się do snu.", "Prorok ﷺ odmawiał to przed snem."),
        "dua_travel" to DuaText("Modlitwa podróżna", "Chwała Temu, który podporządkował nam to, chociaż sami nie mielibyśmy nad tym władzy; i zaprawdę do naszego Pana powrócimy.", "Odmawiane po wsiadaniu do pojazdu, po trzykrotnym takbirze.", "Zalecana modlitwa podróżna dla ochrony i błogosławieństwa."),
        "dua_ayatul_kursi" to DuaText("Ajat al-Kursi po modlitwie", "Allah! Nie ma boga, jak tylko On – Żyjący, Absolutnie Istniejący. Nie dosięga Go ani drzemka, ani sen. Do Niego należy to, co jest w niebiosach, i to, co jest na ziemi. Któż będzie się wstawiał u Niego inaczej jak za Jego pozwoleniem? On wie, co było przed nimi, i On wie, co będzie po nich. Oni nie obejmują niczego z Jego wiedzy, jak tylko to, co On zechce. Jego tron obejmuje niebiosa i ziemię i nie jest Mu trudno ich utrzymać. On jest Wyniosły, Ogromny!", "Odmawiane po każdej obowiązkowej modlitwie i przed snem.", "Kto odmówi to po każdej obowiązkowej modlitwie, jedynie śmierć powstrzyma go przed wejściem do Raju; kto odmówi przed snem, jest chroniony do rana."),
        "dua_hasbunallah" to DuaText("Allah nam wystarczy", "Allah nam wystarczy i On jest najlepszym opiekunem.", "Odmawiane w obliczu strachu przed wrogiem lub wielkim niebezpieczeństwem.", "Powiedział to Ibrahim, gdy został wrzucony w ogień, a Prorok ﷺ w chwili niebezpieczeństwa."),
        "dua_entering_home" to DuaText("Wchodząc do domu", "W imię Allaha wchodzimy, w imię Allaha wychodzimy, i na naszym Panu Allahu polegamy.", "Odmawiane przy wchodzeniu do domu, wspominając imię Allaha i pozdrawiając.", "Do tego, kto wspomina Allaha wchodząc do domu i podczas jedzenia, szatan mówi: nie ma dla was ani noclegu, ani kolacji."),
        "dua_yunus" to DuaText("Modlitwa proroka Junusa (pokój z nim)", "Nie ma boga prócz Ciebie! Niech Ci będzie chwała! Zaprawdę, byłem z niesprawiedliwych!", "Modlitwa proroka Junusa we wnętrzu ryby — na każdą trudność.", "Żaden muzułmanin nie wzywa nią Allaha w żadnej sprawie, by Ten mu nie odpowiedział."),
        "dua_karb" to DuaText("Modlitwa w wielkim utrapieniu", "Nie ma boga prócz Allaha, Wielkiego, Łagodnego. Nie ma boga prócz Allaha, Pana potężnego tronu. Nie ma boga prócz Allaha, Pana niebios, ziemi i szlachetnego tronu.", "Odmawiane w chwilach wielkiego utrapienia i ucisku.", "Prorok ﷺ odmawiał to w chwilach utrapienia."),
    )
}
